# -*- coding: utf-8 -*-
"""Подсчёт упоминаний тем перечня в тексте издания (для отнесения издания к вопросам)."""
import re
RX = {
 'общ': r'криминалистическ\w+ тактик|тактическ\w+ (при[её]м|комбинац|операци|решени|риск)|следственн\w+ ситуаци',
 'осмотр': r'осмотр',
 'одор': r'запахов|одоролог|микрообъект|микрочастиц|микросле',
 'освид': r'освидетельствован',
 'задерж': r'задержан',
 'допрос': r'допрос',
 'очн': r'очн\w+ ставк',
 'опозн': r'опознани',
 'обыск': r'обыск|выемк',
 'экспер': r'следственн\w+ эксперимент',
 'ппм': r'проверк\w+ показаний на месте',
 'кзп': r'контрол\w+ и запис\w+|запис\w+ (телефонных|переговоров)|фонограмм',
 'несов': r'несовершеннолетн',
 'фикс': r'видеозапис|фотосъ[её]мк|видеосъ[её]мк|протокол',
}
def count(text):
    t = ' '.join(text.lower().replace('ё', 'е').replace('-\n', '').split())
    return {k: len(re.findall(v.replace('[её]', 'е'), t)) for k, v in RX.items()}
